import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第三册：培养技能 · Lesson 22 By heart","description":"学习 should have done 的过去评价，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 22 By heart","description":"学习 should have done 的过去评价，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 should have done 的过去评价，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 21 Daniel Mendoza","link":"/life/english/new-concept/book-3/unit-02/lesson-021"},"next":{"text":"第三册：培养技能 · Lesson 23 One man's meat is another man's poison","link":"/life/english/new-concept/book-3/unit-02/lesson-023"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 21 Daniel Mendoza","link":"/life/english/new-concept/book-3/unit-02/lesson-021"},"next":{"text":"第三册：培养技能 · Lesson 23 One man's meat is another man's poison","link":"/life/english/new-concept/book-3/unit-02/lesson-023"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-022.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-022.md"}`),s={name:"life/english/new-concept/book-3/unit-02/lesson-022.md"};function l(i,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-22-by-heart" tabindex="-1">第三册：培养技能 · Lesson 22 By heart <a class="header-anchor" href="#第三册-培养技能-·-lesson-22-by-heart" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 22 By heart&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从舞台台词、记忆和临场补救学习说明意外发生时原本应当完成的准备。背诵不只是复读次数，还涉及提示、理解和提取。学习 should have done 表达过去未实现的责任或事后建议，并把这种评价与实际完成的动作明确区分。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>rehearse</td><td>/rɪˈhɜːs/</td><td>v.</td><td>排练</td><td>rehearse a scene</td></tr><tr><td>prompt</td><td>/prɒmpt/</td><td>n.</td><td>提示</td><td>a verbal prompt</td></tr><tr><td>memorize</td><td>/ˈmeməraɪz/</td><td>v.</td><td>记住</td><td>memorize a speech</td></tr><tr><td>cue</td><td>/kjuː/</td><td>n.</td><td>提示信号</td><td>miss a cue</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>learn by heart — 熟记到能脱离文本复述</li><li>lose one&#39;s place — 忘记读到或说到哪里</li></ul><h2 id="语法讲解-should-have-done-的过去评价" tabindex="-1">语法讲解：should have done 的过去评价 <a class="header-anchor" href="#语法讲解-should-have-done-的过去评价" aria-label="Permalink to &quot;语法讲解：should have done 的过去评价&quot;">​</a></h2><p>should have 加过去分词常表示过去本该做而未做，带有遗憾或批评；shouldn&#39;t have done 常表示做了不该做的事。它也可在特定上下文表示对过去或现在完成情况的合理预期，如包裹按安排应已到达，因此不能见到结构就断言未发生。判断要看上下文是否明确出现失误。must have done 则通常是较强的过去推断，不等同于过去义务。评价他人准备工作时，应说明根据和后果，而非单独一句责备。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I missed my cue because I had not rehearsed; I should have checked the recording twice.</p></blockquote><p>我因为没有排练而错过提示；我本该检查两遍录音。</p><p>had not rehearsed 交代此前缺失的准备；should have checked 评价未完成的适当行动。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I should checked 错缺 have；过去评价用 should have checked，当前建议用 should check。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先遮住示范复述，再对照文本；听辨 should have practised 与 should practise 的区别，记录自己漏掉的助动词。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I forgot the opening line during the rehearsal. I should have practised without looking at my notes. Tomorrow I will use three picture cues instead of a full script.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句演讲复盘，包含一次失误、原因和具体改进。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>过去评价之后给出可操作的未来策略，避免只重复“多努力”。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>本例中说话者是否充分排练？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> had not rehearsed 明确否定。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>将“我不该跳过排练”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I shouldn&#39;t have skipped the rehearsal.</p><p><strong>解析：</strong> 对已做的不当动作进行过去评价。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>must have forgotten 表示义务还是推断？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 推断。</p><p><strong>解析：</strong> must have done 常根据线索推断过去。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：should have done 的过去评价。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-021">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-023">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(s,[["render",l]]);export{p as __pageData,m as default};
